   Design tokens
   ===================================================== */
:root {
  --color-bg:             #0f1117;
  --color-surface:        #1a1d27;
  --color-border:         #2e3145;
  --color-text-primary:   #e2e8f0;
  --color-text-secondary: #94a3b8;
  --color-accent:         #6366f1;
  --color-accent-hover:   #818cf8;
  --color-error:          #fca5a5;
  --color-success:        #4ade80;
  --color-focus:          #818cf8;
  --radius-card:          12px;
  --radius-control:       6px;
}

/* =====================================================
   Reset
   ===================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* =====================================================
   Skip link
   ===================================================== */
.skip-link {
  position: absolute;
  top: -9999px;
  left: -9999px;
  background: var(--color-surface);
  color: var(--color-text-primary);
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-control);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  border: 2px solid var(--color-focus);
}
.skip-link:focus {
  top: 1rem;
  left: 1rem;
}

/* =====================================================
   Utility: visually hidden but available to AT
   ===================================================== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* =====================================================
   Layout
   ===================================================== */
body {
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

main {
  width: 100%;
  max-width: 480px;
}

/* =====================================================
   Card
   ===================================================== */
.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  padding: 2.5rem 2rem;
}

.form-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 0.5rem;
}

.form-description {
  color: var(--color-text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 1.75rem;
}

/* =====================================================
   Required note
   ===================================================== */
.required-note {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-bottom: 1.25rem;
}

/* =====================================================
   Form field wrapper
   ===================================================== */
.form-field {
  margin-bottom: 1.75rem;
}

/* =====================================================
   Checkbox + label row
   ===================================================== */
.checkbox-wrapper {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.375rem;
}

/* Custom checkbox */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.15rem; /* optical alignment with first line of label */
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background-color: transparent;
  cursor: pointer;
  position: relative;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

@media (prefers-reduced-motion: reduce) {
  input[type="checkbox"] { transition: none; }
}

input[type="checkbox"]:hover {
  border-color: var(--color-accent-hover);
}

input[type="checkbox"]:checked {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
}

/* Checkmark */
input[type="checkbox"]:checked::after {
  content: '';
  position: absolute;
  top: 1px;
  left: 4px;
  width: 6px;
  height: 10px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 3px;
}

input[type="checkbox"][aria-invalid="true"] {
  border-color: var(--color-error);
}

label {
  font-size: 0.9375rem;
  color: var(--color-text-primary);
  cursor: pointer;
  line-height: 1.5;
}

/* =====================================================
   Link (inside label)
   ===================================================== */
.link {
  color: var(--color-accent-hover);
  text-underline-offset: 2px;
}
.link:hover {
  color: var(--color-text-primary);
}
.link:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* =====================================================
   Helper and error text
   ===================================================== */
.helper-text,
.error-text {
  font-size: 0.875rem;
  /* Indent to align with label text (checkbox width + gap) */
  padding-left: 2rem;
}

.helper-text {
  color: var(--color-text-secondary);
}

.error-text {
  color: var(--color-error);
  margin-top: 0.375rem;
}

.error-text[hidden] {
  display: none;
}

/* =====================================================
   Submit button
   ===================================================== */
.submit-btn {
  width: 100%;
  padding: 0.75rem 1.5rem;
  background-color: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-control);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

@media (prefers-reduced-motion: reduce) {
  .submit-btn { transition: none; }
}

.submit-btn:hover {
  background-color: var(--color-accent-hover);
}

.submit-btn:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 3px;
}

/* =====================================================
   Success state
   ===================================================== */
.success-card {
  text-align: center;
}

.success-icon {
  font-size: 3rem;
  color: var(--color-success);
  margin-bottom: 1rem;
}

/* =====================================================
   Forced-colors (Windows High Contrast)
   ===================================================== */
@media (forced-colors: active) {
  input[type="checkbox"] { forced-color-adjust: auto; }
  .submit-btn            { forced-color-adjust: auto; }
}

/* =====================================================
   Reflow: narrow viewport (320 CSS px)
   ===================================================== */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1rem;
  }
}
